  const [unpaidLegalRecs, setUnpaidLegalRecs] = useState([]);
  const [unpaidLegalModal, setUnpaidLegalModal] = useState(null);

  // Compliance follow-up actions per EC. Shape:
  // { [ec]: { workPermitRequestedAt, workPermitRequestedBy,
